-- =============================================================================
-- 543 — LE CAHIER D'EXERCICES DE 1RE (partie 31)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 543 --niveau 1re --fichiers physique-chimie.n1,physique-chimie.n2 --suffixe 31 > supabase/contenu/543_exercices_1re_31.sql
--
-- 66 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   physique-chimie.n1      33 exercices · 11 chapitres
--   physique-chimie.n2      33 exercices · 11 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('4db5d1ee-5647-5dd3-9e48-619d3a3908f6'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Maya plonge dans le lac","competence":"lire-graphique","situation":"Maya plonge dans un lac de plaine. Son ordinateur de plongée enregistre la pression de l’eau à chaque profondeur.","documents":[{"id":"courbe","type":"graphique","forme":"courbe","titre":"Pression en fonction de la profondeur","categories":["0 m","10 m","20 m","30 m","40 m"],"series":[{"nom":"Pression","valeurs":[1,2,3,4,5],"teinte":"bleu"}],"axeY":{"titre":"Pression","unite":"bar","min":0,"max":6,"pas":1},"axeX":{"titre":"Profondeur"},"valeurs":false,"source":"Eau douce, g arrondi à 10 N/kg"}],"questions":[{"enonce":"Touche la profondeur à laquelle la pression atteint 3 bar.","aide":"Repère 3 bar sur l’axe vertical, puis lis la profondeur sous le point.","type":"zone","document":"courbe","multiple":false},{"enonce":"De combien de bars la pression augmente-t-elle chaque fois que Maya descend de 10 m ?","aide":"Compare deux points voisins de la courbe.","type":"nombre","unite":"bar"},{"enonce":"Convertis en pascals la pression à 30 m (1 bar = 100 000 Pa).","aide":"Lis d’abord la pression en bar à 30 m.","type":"nombre","unite":"Pa"},{"enonce":"À 0 m, la courbe indique 1 bar. Que représente cette valeur ?","aide":"À la surface, il n’y a pas encore d’eau au-dessus de Maya.","type":"choix","options":[{"id":"a","texte":"La pression de l’air au-dessus du lac"},{"id":"b","texte":"La pression au fond du lac"},{"id":"c","texte":"La pression de l’eau seule"},{"id":"d","texte":"Une pression nulle, sans eau ni air"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"À **20 m** la courbe passe par 3 bar : la pression est celle de l’air (1 bar) plus celle de 20 m d’eau."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1 bar","explication":"On passe de 1 à 2 bar, puis de 2 à 3 bar… : la pression augmente de **1 bar** tous les 10 m."},{"cle":{"type":"nombre","valeur":400000,"tolerance":0},"affichage":"400 000 Pa","explication":"À 30 m, p = 4 bar. 4 × 100 000 = **400 000 Pa**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Au niveau de l’eau, seule l’atmosphère appuie : c’est la **pression atmosphérique**, environ 1 bar (1 013 hPa)."}]$ex$::jsonb),
  ('4db5d1ee-5647-5dd3-9e48-619d3a3908f6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Bastien enferme de l’air dans une seringue","competence":"experimenter","situation":"Bastien bouche l’embout d’une seringue de 60 mL et enfonce le piston lentement, à température constante. Il note le volume de l’air et sa pression. Un de ses relevés est faux.","documents":[{"id":"releves","type":"tableau","titre":"Relevés de Bastien","colonnes":["Mesure","Relevé 1","Relevé 2","Relevé 3","Relevé 4","Relevé 5"],"lignes":[["Volume V (mL)",60,40,30,24,20],["Pression p (kPa)",100,150,220,250,300]],"source":"Valeurs arrondies, écrites pour l’exercice"}],"questions":[{"enonce":"Un seul relevé de pression ne respecte pas la loi de Mariotte. Touche-le.","aide":"Calcule p × V pour chaque colonne et cherche l’intrus.","type":"zone","document":"releves","multiple":false},{"enonce":"Quelle est la valeur du produit p × V pour les relevés justes ?","aide":"Multiplie la pression par le volume sur le premier relevé.","type":"nombre","unite":"kPa·mL"},{"enonce":"Quelle pression Bastien obtiendrait-il en réduisant le volume à 15 mL ?","aide":"p × V reste égal à la même constante.","type":"nombre","unite":"kPa"},{"enonce":"Quelle condition doit rester vraie pendant toute l’expérience pour que p × V soit constant ?","aide":"Relis l’énoncé de la loi : « à … constante ».","type":"choix","options":[{"id":"a","texte":"Le piston est enfoncé le plus vite possible"},{"id":"b","texte":"Le volume du gaz reste le même"},{"id":"c","texte":"La température du gaz ne change pas"},{"id":"d","texte":"La seringue contient de l’eau"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c3"]},"explication":"Les relevés justes donnent p × V = 6 000. Pour 30 mL, 220 × 30 = 6 600 : la pression attendue est **200 kPa**."},{"cle":{"type":"nombre","valeur":6000,"tolerance":0},"affichage":"6000 kPa·mL","explication":"Loi de Mariotte : p × V = constante. 100 × 60 = 150 × 40 = **6 000 kPa·mL**."},{"cle":{"type":"nombre","valeur":400,"tolerance":0},"affichage":"400 kPa","explication":"p = constante / V = 6 000 / 15 = **400 kPa**."},{"cle":{"type":"choix","ids":["c"]},"explication":"La loi de Mariotte vaut pour un gaz **à température constante** : on enfonce le piston lentement pour que l’air ne s’échauffe pas."}]$ex$::jsonb),
  ('4db5d1ee-5647-5dd3-9e48-619d3a3908f6'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"L’iceberg et ses neuf dixièmes","competence":"raisonner","situation":"Au large du Groenland, un navire croise un iceberg. Mélina veut comprendre pourquoi on n’en voit qu’une petite partie et ce qui se passerait dans un lac d’eau douce.","documents":[{"id":"masses","type":"tableau","titre":"Masses volumiques (kg/m³)","colonnes":["Matériau","ρ (kg/m³)"],"lignes":[["Liège",240],["Chêne",750],["Glace",920],["Fer",7800],["Eau de mer",1030],["Eau douce",1000]],"source":"Valeurs arrondies"},{"id":"iceberg","type":"schema","titre":"Un iceberg qui flotte","largeur":340,"hauteur":220,"elements":[{"forme":"rect","x":20,"y":90,"l":300,"h":110,"teinte":"bleu","motif":"clair"},{"forme":"polygone","points":[[120,90],[148,48],[172,62],[198,28],[232,90]],"teinte":"blanc","motif":"plein","id":"z1","zone":true},{"forme":"polygone","points":[[120,90],[232,90],[262,128],[226,176],[160,188],[108,150]],"teinte":"ciel","motif":"plein","id":"z2","zone":true},{"forme":"ligne","de":[20,90],"a":[320,90],"style":"pointilles"},{"forme":"texte","x":60,"y":50,"texte":"Air","taille":"petit"},{"forme":"texte","x":255,"y":194,"texte":"Eau de mer","taille":"petit","ancre":"milieu"}]}],"questions":[{"enonce":"Dans l’eau de mer, range chaque matériau : flotte-t-il ou coule-t-il ?","aide":"Compare la masse volumique du matériau à celle de l’eau de mer.","type":"categories","categories":[{"id":"c0","texte":"Il flotte"},{"id":"c1","texte":"Il coule"}],"items":[{"id":"i0","texte":"Glace"},{"id":"i1","texte":"Liège"},{"id":"i2","texte":"Fer"},{"id":"i3","texte":"Chêne"}]},{"enonce":"Touche la partie de l’iceberg qui est immergée.","aide":"La ligne pointillée représente la surface de l’eau.","type":"zone","document":"iceberg","multiple":false},{"enonce":"Quel pourcentage du volume de la glace est immergé dans l’eau de mer ? (arrondi à l’unité)","aide":"Le corps flotte : poussée = poids, donc ρ(fluide) × V(immergé) = ρ(glace) × V(total).","type":"nombre","unite":"%"},{"enonce":"Le même bloc de glace flotte dans un lac d’eau douce. Quel pourcentage de son volume est immergé ?","aide":"Même raisonnement, avec la masse volumique de l’eau douce.","type":"nombre","unite":"%"},{"enonce":"Quand le fluide est moins dense, que devient la partie immergée d’un même corps qui flotte ?","aide":"Compare tes deux résultats : 89 % puis 92 %.","type":"choix","options":[{"id":"a","texte":"Elle disparaît"},{"id":"b","texte":"Elle augmente"},{"id":"c","texte":"Elle diminue"},{"id":"d","texte":"Elle ne change pas"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Un corps flotte si sa masse volumique est inférieure à celle du fluide (1 030 kg/m³) : liège, chêne et glace flottent ; le **fer** (7 800) coule."},{"cle":{"type":"zone","ids":["z2"]},"explication":"La partie **sous la surface de l’eau** est la partie immergée : c’est la plus grande."},{"cle":{"type":"nombre","valeur":89,"tolerance":0},"affichage":"89 %","explication":"V(immergé) / V = ρ(glace) / ρ(eau de mer) = 920 / 1 030 ≈ 0,89, soit **89 %**."},{"cle":{"type":"nombre","valeur":92,"tolerance":0},"affichage":"92 %","explication":"V(immergé) / V = 920 / 1 000 = 0,92, soit **92 %**."},{"cle":{"type":"choix","ids":["b"]},"explication":"V(immergé) / V = ρ(corps) / ρ(fluide) : si ρ(fluide) diminue, la fraction immergée **augmente**."}]$ex$::jsonb),
  ('255929a5-1e83-5840-8f4e-dfbbddfbbdef'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Léa lit dans le TGV","competence":"raisonner","situation":"Léa est assise dans un train. Hugo, sur le quai, la voit passer. Ils échangent des messages.","documents":[{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"Je suis dans le TGV et je n’ai pas bougé de mon siège depuis Paris !"},{"qui":"Hugo","texte":"Moi, sur le quai, je te vois filer à 72 km/h au passage de la gare."},{"qui":"Léa","texte":"Pourtant je lis tranquillement mon livre !"}]}],"questions":[{"enonce":"Touche les deux mots qui désignent chacun un référentiel.","aide":"Un référentiel est un objet auquel on rattache l’observateur : le train ou le quai.","type":"zone","document":"sms","multiple":true},{"enonce":"Associe chaque référentiel à ce que l’on dit de Léa.","aide":"Léa est-elle au même endroit par rapport à son siège ? Et par rapport au quai ?","type":"association","gauche":[{"id":"g0","texte":"Dans le référentiel du train"},{"id":"g1","texte":"Dans le référentiel du quai"}],"droite":[{"id":"d0","texte":"Léa est en mouvement"},{"id":"d1","texte":"Léa est immobile"}]},{"enonce":"Convertis la vitesse du train en m/s (divise par 3,6).","aide":"1 km/h = 1 000 m par 3 600 s.","type":"nombre","unite":"m/s"},{"enonce":"Quelle distance le train parcourt-il en 15 s à cette vitesse ?","aide":"v = d / t, donc d = v × t.","type":"nombre","unite":"m"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m19"]},"explication":"Léa décrit le mouvement dans le référentiel du **TGV**, Hugo dans celui du **quai** (le sol)."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"Par rapport au train, Léa ne bouge pas ; par rapport au sol, elle avance avec le train. Le mouvement **dépend du référentiel**."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 m/s","explication":"72 / 3,6 = **20 m/s**."},{"cle":{"type":"nombre","valeur":300,"tolerance":0},"affichage":"300 m","explication":"d = 20 × 15 = **300 m**."}]$ex$::jsonb),
  ('255929a5-1e83-5840-8f4e-dfbbddfbbdef'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Sacha freine devant le feu rouge","competence":"lire-graphique","situation":"Sacha roule à 72 km/h quand le feu passe au rouge. Il freine à fond en ligne droite. Son tableau de bord a enregistré sa vitesse chaque seconde.","documents":[{"id":"vitesse","type":"graphique","forme":"courbe","titre":"Vitesse de la voiture pendant le freinage","categories":["0 s","1 s","2 s","3 s","4 s","5 s"],"series":[{"nom":"Vitesse","valeurs":[20,16,12,8,4,0],"teinte":"violet"}],"axeY":{"titre":"Vitesse","unite":"m/s","min":0,"max":24,"pas":4},"axeX":{"titre":"Temps"},"valeurs":false,"source":"Valeurs arrondies, écrites pour l’exercice"}],"questions":[{"enonce":"Touche l’instant où la voiture est à l’arrêt.","aide":"À l’arrêt, la vitesse est nulle.","type":"zone","document":"vitesse","multiple":false},{"enonce":"De combien la vitesse diminue-t-elle chaque seconde ? (valeur de l’accélération, sans le signe)","aide":"a = Δv / Δt entre deux instants successifs.","type":"nombre","unite":"m/s²"},{"enonce":"La vitesse moyenne vaut 10 m/s sur ces 5 s. Quelle distance Sacha parcourt-il jusqu’à l’arrêt ?","aide":"d = vitesse moyenne × durée.","type":"nombre","unite":"m"},{"enonce":"Quelle est la direction et le sens du vecteur accélération pendant le freinage ?","aide":"La vitesse diminue : l’accélération s’oppose au mouvement.","type":"choix","options":[{"id":"a","texte":"Le vecteur accélération est nul"},{"id":"b","texte":"Même direction et même sens que la vitesse"},{"id":"c","texte":"Même direction que la vitesse, sens opposé"},{"id":"d","texte":"Perpendiculaire à la vitesse"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k5"]},"explication":"La vitesse atteint 0 m/s à **5 s**."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 m/s²","explication":"a = (20 − 0) / 5 = **4 m/s²** : la vitesse varie linéairement, le mouvement est rectiligne uniformément décéléré."},{"cle":{"type":"nombre","valeur":50,"tolerance":0},"affichage":"50 m","explication":"d = 10 × 5 = **50 m** de freinage."},{"cle":{"type":"choix","ids":["c"]},"explication":"La variation du vecteur vitesse est dirigée vers l’arrière : l’accélération est **de même direction que la vitesse mais de sens opposé**."}]$ex$::jsonb),
  ('255929a5-1e83-5840-8f4e-dfbbddfbbdef'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Noé lâche une balle depuis le balcon","competence":"modeliser","situation":"Noé lâche une balle du balcon et la filme. En pointant la vidéo image par image, il relève la vitesse de la balle. Son frère affirme qu’une balle lourde tombe plus vite qu’une balle légère.","documents":[{"id":"releve","type":"tableau","titre":"Pointage de la chute","colonnes":["Mesure","Départ","Image 1","Image 2","Image 3","Image 4"],"lignes":[["Temps t (s)",0,0.1,0.2,0.3,0.4],["Vitesse v (m/s)",0,0.98,1.96,2.94,3.92]],"source":"Valeurs arrondies, écrites pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Noé","emoji":"👦","cote":"gauche"},{"nom":"Yanis","emoji":"🧒","cote":"droite"}],"repliques":[{"qui":"Yanis","texte":"Une balle de 5 kg tombe plus vite qu’une balle de tennis de 58 g, c’est évident."},{"qui":"Noé","texte":"Alors mesurons l’accélération de la balle de tennis, sans frottements de l’air."}]}],"questions":[{"enonce":"Quelle est l’accélération de la balle (a = Δv / Δt entre le départ et l’image 4) ?","aide":"Divise la variation de vitesse par la durée écoulée.","type":"nombre","unite":"m/s²"},{"enonce":"En chute libre (seule la pesanteur agit), qui a raison ?","aide":"Applique la deuxième loi : Σ F = m × a, avec F = m × g.","type":"choix","options":[{"id":"a","texte":"La balle de 5 kg accélère davantage"},{"id":"b","texte":"La balle de tennis accélère davantage"},{"id":"c","texte":"On ne peut pas le savoir"},{"id":"d","texte":"Les deux balles ont la même accélération"}],"multiple":false},{"enonce":"Si la chute se prolonge, quelle serait la vitesse à t = 0,6 s ?","aide":"L’accélération est constante : la vitesse varie linéairement avec le temps.","type":"nombre","unite":"m/s"},{"enonce":"Combien de temps dure la chute depuis un balcon à 4,9 m ? (h = ½ × g × t²)","aide":"Isole t² : t² = 2h / g.","type":"nombre","unite":"s"},{"enonce":"Remets dans l’ordre la méthode pour étudier ce mouvement.","aide":"On commence par dire ce qu’on étudie, on finit par la position.","type":"ordre","items":[{"id":"a","texte":"Appliquer la deuxième loi pour obtenir l’accélération"},{"id":"b","texte":"Définir le système : la balle"},{"id":"c","texte":"Intégrer pour obtenir la vitesse puis la position"},{"id":"d","texte":"Choisir le référentiel : le sol"},{"id":"e","texte":"Faire le bilan des forces : le poids seul"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":9.8,"tolerance":0},"affichage":"9,8 m/s²","explication":"a = (3,92 − 0) / 0,4 = **9,8 m/s²**, c’est la valeur de g."},{"cle":{"type":"choix","ids":["d"]},"explication":"P = m × g et P = m × a donnent **a = g**, quelle que soit la masse : la chute libre est indépendante de la masse."},{"cle":{"type":"nombre","valeur":5.88,"tolerance":0.01},"affichage":"5,88 m/s","explication":"v = g × t = 9,8 × 0,6 = **5,88 m/s**."},{"cle":{"type":"nombre","valeur":1,"tolerance":0.01},"affichage":"1 s","explication":"t² = 2 × 4,9 / 9,8 = 1, donc t = **1,0 s**."},{"cle":{"type":"ordre","ids":["b","d","e","a","c"]},"explication":"Système, référentiel, bilan des forces, deuxième loi, puis intégration : la **méthode est toujours la même**."}]$ex$::jsonb),
  ('7ed0e00f-4c44-549a-9dff-6092baa17ffe'::uuid, 1, 1, 5, 20, 4,
