  ('7ed0e00f-4c44-549a-9dff-6092baa17ffe'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La station spatiale et la gravité","competence":"analyser-document","situation":"Une station spatiale de 400 tonnes tourne autour de la Terre à 400 km d’altitude. Les astronautes y flottent. Louis veut savoir si la pesanteur y est vraiment absente.","documents":[{"id":"gh","type":"graphique","forme":"courbe","titre":"Champ gravitationnel de la Terre selon l’altitude","categories":["0 km","400 km","800 km","1 200 km","1 600 km"],"series":[{"nom":"g","valeurs":[9.8,8.7,7.7,6.9,6.3],"teinte":"violet"}],"axeY":{"titre":"g","unite":"N/kg","min":0,"max":12,"pas":2},"axeX":{"titre":"Altitude"},"valeurs":false,"source":"Calculé avec g = G × M / (R + h)²"},{"id":"don","type":"tableau","titre":"Données","colonnes":["Grandeur","Valeur"],"lignes":[["Constante de gravitation G","6,67 × 10⁻¹¹ (SI)"],["Masse de la Terre M","5,97 × 10²⁴ kg"],["Rayon de la Terre R","6 371 km"]]}],"questions":[{"enonce":"Touche l’altitude où le champ gravitationnel vaut environ 7,7 N/kg.","aide":"Cherche 7,7 sur l’axe vertical, puis descends vers l’altitude.","type":"zone","document":"gh","multiple":false},{"enonce":"Calcule g à 400 km d’altitude (d = R + h = 6 771 km). Arrondis au dixième.","aide":"g = G × M / d², avec d en mètres.","type":"nombre","unite":"N/kg"},{"enonce":"Quelle force la Terre exerce-t-elle sur la station de 400 t ? Réponds en MN (méganewtons), arrondi au dixième.","aide":"Convertis 400 t en kilogrammes, puis F = m × g.","type":"nombre","unite":"MN"},{"enonce":"Pourquoi les astronautes flottent-ils dans la station ?","aide":"Compare avec g à 400 km : est-il nul ?","type":"choix","options":[{"id":"a","texte":"Ils tombent librement avec la station autour de la Terre"},{"id":"b","texte":"La gravité devient répulsive loin de la surface"},{"id":"c","texte":"Leur masse devient nulle dans l’espace"},{"id":"d","texte":"Il n’y a plus du tout de gravité à cette altitude"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"Le point à **800 km** est à 7,7 N/kg : g diminue quand l’altitude augmente."},{"cle":{"type":"nombre","valeur":8.7,"tolerance":0.05},"affichage":"8,7 N/kg","explication":"g = 6,67 × 10⁻¹¹ × 5,97 × 10²⁴ / (6,771 × 10⁶)² ≈ **8,7 N/kg**."},{"cle":{"type":"nombre","valeur":3.5,"tolerance":0.05},"affichage":"3,5 MN","explication":"F = 400 000 × 8,7 ≈ 3,5 × 10⁶ N, soit **3,5 MN**."},{"cle":{"type":"choix","ids":["a"]},"explication":"À 400 km, g vaut encore 8,7 N/kg. Les astronautes flottent parce qu’ils sont, comme la station, **en chute libre** autour de la Terre."}]$ex$::jsonb),
