che"}],"multiple":false},{"enonce":"Calcule le champ gravitationnel de la Terre à la distance de la Lune, en 10⁻³ N/kg, arrondi au dixième.","aide":"g = G × M / d², avec la masse de la Terre.","type":"nombre","unite":"× 10⁻³ N/kg"},{"enonce":"Complète : on rapproche les deux astres.","aide":"La force varie en 1 / d².","type":"trous","segments":["Si la distance était divisée par 3, la force serait multipliée par ",0,"."],"banque":["9","6","3","27"]}]}$ex$::jsonb,
