   $ex${"titre":"Freiner à 50 ou à 100 km/h","competence":"argumenter","situation":"Une voiture de 1 000 kg freine avec des frottements constants de 7 000 N. Amine affirme qu’à 100 km/h, au lieu de 50, la distance de freinage est seulement le double.","documents":[{"id":"tab","type":"tableau","titre":"Énergie cinétique de la voiture","colonnes":["Vitesse (km/h)","Ec (kJ)"],"lignes":[["30",35],["50",96],["70",189],["90",312.5]],"source":"Valeurs arrondies, Ec = ½ × m × v² avec m = 1 000 kg"},{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Amine","emoji":"🧑","cote":"gauche"},{"nom":"Prof","emoji":"🧑‍🏫","cote":"droite"}],"repliques":[{"qui":"Amine","texte":"À 100 au lieu de 50, je mets simplement deux fois plus de distance pour freiner."},{"qui":"Prof","texte":"Appliquons le théorème de l’énergie cinétique pour vérifier."}]}],"questions":[{"enonce":"Touche l’énergie cinétique à 50 km/h.","aide":"Cherche la ligne 50 km/h.","type":"zone","document":"tab","multiple":false},{"enonce":"Quelle est la distance de freinage à 50 km/h ? (ΔEc = −F × d, avec F = 7 000 N et Ec = 96 450 J), arrondie au dixième.","aide":"Le travail des frottements est −F × d : il annule l’énergie cinétique.","type":"nombre","unite":"m"},{"enonce":"Quelle est la distance de freinage à 100 km/h ? (Ec = 385 800 J), arrondie au dixième.","aide":"Même méthode, avec l’énergie cinétique à 100 km/h.","type":"nombre","unite":"m"},{"enonce":"Que penser de l’affirmation d’Amine ?","aide":"Ec dépend du carré de v, et d = Ec / F.","type":"choix","options":[{"id":"a","texte":"Fausse : doubler la vitesse multiplie la distance par 4"},{"id":"b","texte":"Vraie : la distance ne dépend que de la masse"},{"id":"c","texte":"Vraie : la distance double quand la vitesse double"},{"id":"d","texte":"Fausse : la distance de freinage reste la même"}],"multiple":false},{"enonce":"Quelle énergie est transférée au milieu sous forme thermique pendant le freinage à 50 km/h ? (arrondie au kJ)","aide":"L’énergie mécanique disparaît : où va-t-elle ?","type":"nombre","unite":"kJ"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"À 50 km/h, Ec ≈ **96 kJ** (96 450 J)."},{"cle":{"type":"nombre","valeur":13.8,"tolerance":0.05},"affichage":"13,8 m","explication":"0 − 96 450 = −7 000 × d, donc d ≈ **13,8 m**."},{"cle":{"type":"nombre","valeur":55.1,"tolerance":0.05},"affichage":"55,1 m","explication":"d = 385 800 / 7 000 ≈ **55,1 m**, soit quatre fois plus qu’à 50 km/h."},{"cle":{"type":"choix","ids":["a"]},"explication":"Ec ∝ v², donc d ∝ v² : à vitesse double, la distance est **multipliée par 4**."},{"cle":{"type":"nombre","valeur":96,"tolerance":0.6},"affichage":"96 kJ","explication":"ΔEm = W(frottements) = −96 kJ : cette énergie, **96 kJ**, est dissipée sous forme thermique (freins, pneus, air)."}]$ex$::jsonb),
