   $ex${"titre":"Pourquoi les lignes à haute tension ?","competence":"modeliser","situation":"Une ville consomme 2,0 MW. L’électricité est transportée par une ligne de résistance 5,0 Ω. Karim compare le transport sous 20 kV et sous 400 kV.","documents":[{"id":"don","type":"tableau","titre":"Données de la ligne","colonnes":["Donnée","Valeur"],"lignes":[["Puissance transportée P","2,0 MW"],["Résistance de la ligne R","5,0 Ω"],["Tension de transport (cas 1)","20 kV"],["Tension de transport (cas 2)","400 kV"]]},{"id":"circ","type":"circuit","titre":"Le transport vers la ville","branches":[{"de":[0,4],"a":[0,0],"composant":"generateur","nom":"Centrale"},{"de":[0,0],"a":[4,0]},{"de":[4,0],"a":[8,0],"composant":"resistance","nom":"R","id":"z1"},{"de":[8,0],"a":[8,4],"composant":"lampe","nom":"Ville","id":"z2","allume":true},{"de":[8,4],"a":[0,4]}]}],"questions":[{"enonce":"Touche le composant qui représente la ligne de transport.","aide":"Les pertes par effet Joule se produisent dans une résistance.","type":"zone","document":"circ","multiple":false},{"enonce":"Quelle est l’intensité dans la ligne sous 20 kV ? (P = U × I)","aide":"Convertis P en watts : 2,0 MW = 2,0 × 10⁶ W.","type":"nombre","unite":"A"},{"enonce":"Quelle puissance est perdue par effet Joule dans la ligne sous 20 kV (P = R × I²), en kW ?","aide":"P perdue = 5,0 × 100².","type":"nombre","unite":"kW"},{"enonce":"Quel est le rendement du transport sous 20 kV, en pourcentage ?","aide":"η = (P − pertes) / P.","type":"nombre","unite":"%"},{"enonce":"On passe de 20 kV à 400 kV (tension multipliée par 20). Que deviennent les pertes en ligne ?","aide":"À puissance égale, I est divisée par 20. Les pertes varient comme I².","type":"choix","options":[{"id":"a","texte":"Divisées par 400"},{"id":"b","texte":"Divisées par 20"},{"id":"c","texte":"Multipliées par 20"},{"id":"d","texte":"Inchangées"}],"multiple":false}]}$ex$::jsonb,
