   $ex${"titre":"Le sirop de menthe bleu au spectrophotomètre","competence":"lire-graphique","situation":"Au lycée, Sana étudie un sirop bleu dilué. Le spectrophotomètre lui donne le spectre d’absorption de la solution : l’absorbance A en fonction de la longueur d’onde λ.","documents":[{"id":"spectre","type":"graphique","forme":"courbe","titre":"Spectre d’absorption du sirop dilué","categories":["400","450","500","550","600","650","700","750"],"series":[{"nom":"Absorbance A","valeurs":[0.05,0.07,0.1,0.22,0.62,0.55,0.2,0.06]}],"axeY":{"titre":"Absorbance A","min":0,"max":0.8,"pas":0.1},"axeX":{"titre":"Longueur d’onde λ (nm)"},"source":"Mesures simulées pour l’exercice"}],"questions":[{"enonce":"Touche la longueur d’onde à laquelle Sana doit régler son spectrophotomètre pour la suite des mesures.","aide":"On travaille là où la solution absorbe le plus.","type":"zone","document":"spectre","multiple":false},{"enonce":"Lis l’absorbance de la solution à 500 nm.","aide":"Repère le point d’abscisse 500 nm, puis lis son ordonnée.","type":"nombre"},{"enonce":"Pourquoi Sana mesure-t-elle à λ(max) plutôt qu’à 450 nm ?","aide":"Au maximum, un petit changement de concentration provoque un grand changement d’absorbance.","type":"choix","options":[{"id":"a","texte":"La variation d’absorbance y est la plus forte, donc la mesure y est la plus sensible"},{"id":"b","texte":"L’absorbance n’y dépend plus de la concentration, ce qui évite toute erreur"},{"id":"c","texte":"La loi de Beer-Lambert n’y est valable que pour une seule concentration"},{"id":"d","texte":"À cette longueur d’onde, la solution n’absorbe plus du tout la lumière"}],"multiple":false},{"enonce":"Le sirop absorbe surtout vers 600 nm (orangé). Quelle couleur la solution a-t-elle pour l’œil ?","aide":"L’œil perçoit la lumière qui n’est pas absorbée.","type":"choix","options":[{"id":"a","texte":"Bleue, la couleur complémentaire de la lumière absorbée"},{"id":"b","texte":"Orange, la couleur même de la lumière absorbée par elle"},{"id":"c","texte":"Verte, car 600 nm est au milieu du spectre visible"},{"id":"d","texte":"Incolore, car elle absorbe toute la lumière qu’elle reçoit"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"On règle l’appareil à **λ(max) = 600 nm**, le maximum d’absorption : la mesure y est la plus sensible."},{"cle":{"type":"nombre","valeur":0.1,"tolerance":0.01},"affichage":"0,1","explication":"À 500 nm, la courbe donne **A = 0,10**. L’absorbance n’a pas d’unité."},{"cle":{"type":"choix","ids":["a"]},"explication":"À λ(max), l’absorbance varie le plus avec la concentration : **sensibilité maximale** et petite erreur de réglage sans conséquence."},{"cle":{"type":"choix","ids":["a"]},"explication":"La solution absorbe l’orangé et nous renvoie le reste : elle paraît **bleue**, couleur complémentaire de l’orangé."}]$ex$::jsonb),
