  ('53cc07d6-5389-5a8b-8f1c-5b86a9e78935'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le ruban de magnésium du feu d’artifice","competence":"calculer","situation":"Dans un feu d’artifice, le magnésium brûle en produisant une lumière blanche éblouissante : 2 Mg + O₂ → 2 MgO. Elsa étudie cette réaction avec 0,30 mol de magnésium et 0,10 mol de dioxygène. On donne M(Mg) = 24,3 g/mol et M(O) = 16,0 g/mol.","documents":[{"id":"tableau","type":"tableau","titre":"Tableau d’avancement","colonnes":["État du système","Mg","O₂","MgO"],"lignes":[["État initial (x = 0)","0,30","0,10","0"],["En cours (x)","0,30 − 2x","0,10 − x","2x"],["État final (x = x max)","?","?","?"]],"enteteLignes":true,"source":"Quantités en mol"}],"questions":[{"enonce":"Touche la case qui donne la quantité de dioxygène à l’état initial.","aide":"Cherche la colonne O₂, puis la ligne de l’état initial.","type":"zone","document":"tableau","multiple":false},{"enonce":"Quelle est la valeur de l’avancement maximal x(max), en mol ?","aide":"Le réactif limitant est épuisé le premier : n(initial) − coefficient × x(max) = 0 pour lui.","type":"nombre","unite":"mol"},{"enonce":"Quelle quantité de magnésium reste-t-il à l’état final, en mol ?","aide":"Remplace x par x(max) dans l’expression 0,30 − 2x.","type":"nombre","unite":"mol"},{"enonce":"Quelle masse d’oxyde de magnésium MgO se forme ? Réponds en g, arrondie au dixième.","aide":"n(MgO) = 2x(max), puis m = n × M avec M(MgO) = 24,3 + 16,0.","type":"nombre","unite":"g"}]}$ex$::jsonb,
