  ('53cc07d6-5389-5a8b-8f1c-5b86a9e78935'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le zinc attaqué par l’acide","competence":"lire-graphique","situation":"Pour son TP, Hugo plonge 1,31 g de zinc (M = 65,4 g/mol) dans 50,0 mL d’acide chlorhydrique à 0,50 mol/L : Zn + 2 H₃O⁺ → Zn²⁺ + H₂ + 2 H₂O. Il recueille le dihydrogène et note son volume. Volume molaire : 24 L/mol.","documents":[{"id":"volume","type":"graphique","forme":"courbe","titre":"Volume de dihydrogène recueilli","categories":["0","1","2","3","4","5","6","7"],"series":[{"nom":"V(H₂)","valeurs":[0,110,190,250,285,300,300,300]}],"axeY":{"titre":"Volume de H₂","unite":"mL","min":0,"max":350,"pas":50},"axeX":{"titre":"Temps (min)"},"source":"Mesures simulées pour l’exercice"}],"questions":[{"enonce":"Touche la première date à laquelle la réaction est terminée.","aide":"Quand la réaction s’arrête, plus aucun gaz ne se dégage : la courbe devient horizontale.","type":"zone","document":"volume","multiple":false},{"enonce":"Quelle quantité de dihydrogène s’est formée au total, en mol ? Arrondie au dix-millième.","aide":"Lis le volume du plateau (en mL), convertis-le en L, puis n = V / V(m).","type":"nombre","unite":"mol"},{"enonce":"Quel est le réactif limitant ? On a n(Zn) = 0,0200 mol et n(H₃O⁺) = 0,0250 mol.","aide":"Divise chaque quantité initiale par son coefficient stœchiométrique avant de comparer.","type":"choix","options":[{"id":"a","texte":"Le zinc, car sa quantité initiale est la plus faible des deux"},{"id":"b","texte":"Aucun : le mélange est stœchiométrique, tout est consommé"},{"id":"c","texte":"Le dihydrogène, car c’est le dernier corps à se former"},{"id":"d","texte":"H₃O⁺ : 0,0250 / 2 = 0,0125, plus petit que 0,0200 / 1"}],"multiple":false},{"enonce":"Quelle masse de zinc reste-t-il à la fin ? Réponds en g, arrondie au centième.","aide":"n(Zn) restant = n(Zn) initial − x(max), puis m = n × M.","type":"nombre","unite":"g"}]}$ex$::jsonb,
