  ('53cc07d6-5389-5a8b-8f1c-5b86a9e78935'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le rendement d’une usine d’ammoniac","competence":"raisonner","situation":"Une usine fabrique de l’ammoniac pour les engrais : N₂ + 3 H₂ → 2 NH₃. Un essai démarre avec 4,0 mol de diazote et 9,0 mol de dihydrogène. On donne M(NH₃) = 17,0 g/mol.","documents":[{"id":"tableau","type":"tableau","titre":"Tableau d’avancement de l’essai","colonnes":["État du système","N₂","+ 3 H₂","→ 2 NH₃"],"lignes":[["État initial (x = 0)","4,0","9,0","0"],["En cours (x)","4,0 − x","9,0 − 3x","2x"],["État final (x = x max)","?","?","?"]],"enteteLignes":true,"source":"Quantités en mol"},{"id":"compte","type":"fiche","modele":"affiche","entete":"Compte rendu de l’essai","sousTitre":"Réacteur à 450 °C, catalyseur à base de fer","emoji":"🏭","lignes":[{"texte":"Ammoniac recueilli","valeur":"85 g","id":"z1"},{"texte":"Pression","valeur":"200 bar"}],"pied":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Touche l’expression qui donne la quantité de dihydrogène en cours de réaction.","aide":"Cherche la colonne H₂ et la ligne « En cours ».","type":"zone","document":"tableau","multiple":false},{"enonce":"Quel est le réactif limitant ?","aide":"Ne compare pas les quantités brutes : divise chacune par son coefficient.","type":"choix","options":[{"id":"a","texte":"Le dihydrogène : 9,0 / 3 = 3,0 est plus petit que 4,0 / 1"},{"id":"b","texte":"Le diazote, car 4,0 mol est inférieur à 9,0 mol"},{"id":"c","texte":"Aucun : les deux sont épuisés ensemble"},{"id":"d","texte":"L’ammoniac, qui se forme en plus petite quantité"}],"multiple":false},{"enonce":"Quelle masse maximale d’ammoniac peut-on former ? Réponds en g.","aide":"x(max) = 3,0 mol ; n(NH₃) = 2x(max) ; puis m = n × M.","type":"nombre","unite":"g"},{"enonce":"Quelle quantité de diazote reste-t-il à l’état final, en mol ?","aide":"Remplace x par x(max) dans 4,0 − x.","type":"nombre","unite":"mol"},{"enonce":"Calcule le rendement de l’essai, en %, arrondi à l’unité.","aide":"Rendement = masse obtenue / masse maximale (même unité).","type":"nombre","unite":"%"}]}$ex$::jsonb,
