  ('c56bcb52-bd04-5593-a12e-30432ee07bef'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le fer du sel de Mohr au laboratoire","competence":"observer-schema","situation":"Au laboratoire, Camille titre 10,0 mL d’une solution de sulfate de fer(II) de concentration inconnue, placés dans un bécher, par une solution de sulfate de cérium(IV) à 0,020 mol/L, versée à la burette : Ce⁴⁺ + Fe²⁺ → Ce³⁺ + Fe³⁺. L’équivalence est repérée par le changement de couleur persistant d’un indicateur coloré, pour un volume versé V(E) = 15,0 mL.","documents":[{"id":"montage","type":"schema","titre":"Le montage de titrage","largeur":320,"hauteur":270,"source":"Schéma simplifié","elements":[{"forme":"rect","x":40,"y":250,"l":240,"h":10,"teinte":"gris","motif":"plein"},{"forme":"rect","x":56,"y":20,"l":8,"h":230,"teinte":"gris","motif":"plein"},{"forme":"ligne","de":[64,80],"a":[140,80],"epaisseur":3},{"forme":"rect","x":140,"y":30,"l":22,"h":140,"arrondi":4,"teinte":"ciel","motif":"clair","id":"z1","zone":true},{"forme":"ligne","de":[143,60],"a":[150,60]},{"forme":"ligne","de":[143,90],"a":[150,90]},{"forme":"ligne","de":[143,120],"a":[150,120]},{"forme":"rect","x":144,"y":170,"l":14,"h":8,"teinte":"encre","motif":"plein"},{"forme":"ligne","de":[151,178],"a":[151,200],"epaisseur":2},{"forme":"rect","x":96,"y":200,"l":110,"h":46,"arrondi":6,"teinte":"bleu","motif":"clair","id":"z2","zone":true},{"forme":"rect","x":136,"y":238,"l":30,"h":5,"arrondi":2,"teinte":"encre","motif":"plein"},{"forme":"texte","x":151,"y":226,"texte":"Fe²⁺","ancre":"milieu"},{"forme":"rect","x":80,"y":246,"l":142,"h":4,"teinte":"gris","motif":"plein"}]}],"questions":[{"enonce":"Touche le récipient qui contient le réactif titrant, de concentration connue.","aide":"Le titrant se verse peu à peu, goutte à goutte, par le haut.","type":"zone","document":"montage","multiple":false},{"enonce":"Touche le récipient qui contient le réactif titré, de concentration inconnue.","aide":"Le titré est prélevé avec précision, puis reçoit le titrant.","type":"zone","document":"montage","multiple":false},{"enonce":"Quelle est la concentration en ions Fe²⁺ de la solution titrée, en mol/L ?","aide":"Les coefficients valent 1 : C(titré) × V(titré) = C(titrant) × V(E).","type":"nombre","unite":"mol/L"},{"enonce":"Camille ajoute par erreur 20 mL d’eau distillée dans le bécher avant de titrer. Que devient le volume équivalent V(E) ?","aide":"À l’équivalence, c’est une quantité de matière qui compte, pas une concentration.","type":"choix","options":[{"id":"a","texte":"Il diminue, car le titré est devenu plus dilué dans le bécher"},{"id":"b","texte":"Il devient nul, car l’eau distillée empêche toute réaction chimique"},{"id":"c","texte":"Il ne change pas : seule la quantité de matière du titré compte"},{"id":"d","texte":"Il double, car le volume du bécher a été multiplié par trois environ"}],"multiple":false}]}$ex$::jsonb,
