   $ex${"titre":"Pourquoi la propanone bout plus haut que le butane","competence":"argumenter","situation":"Un laborantin range deux liquides à masse molaire identique : le butane (gaz de briquet liquéfié) et la propanone (dissolvant). Il compare leurs températures d’ébullition et prépare le choix d’un solvant pour deux solutés.","documents":[{"id":"teb","type":"tableau","titre":"Deux molécules de même masse molaire","colonnes":["Molécule","Formule semi-développée","M (g/mol)","T d’ébullition (°C)"],"lignes":[["Butane","CH₃−CH₂−CH₂−CH₃","58","−1"],["Propanone","CH₃−CO−CH₃","58","56"]],"enteteLignes":true,"source":"Valeurs arrondies"},{"id":"solvants","type":"tableau","titre":"Deux solvants usuels","colonnes":["Solvant","Nature"],"lignes":[["Eau","Polaire"],["Cyclohexane","Apolaire"]],"enteteLignes":true}],"questions":[{"enonce":"Range ces solutés selon le solvant qui les dissout le mieux.","aide":"Semblable dissout semblable : polaire ou ionique avec polaire, apolaire avec apolaire.","type":"categories","categories":[{"id":"c0","texte":"Dans l’eau"},{"id":"c1","texte":"Dans le cyclohexane"}],"items":[{"id":"i0","texte":"Sucre"},{"id":"i1","texte":"Chlorure de sodium NaCl"},{"id":"i2","texte":"Diiode I₂"},{"id":"i3","texte":"Huile de tournesol"}]},{"enonce":"Touche la molécule polaire du tableau, sachant qu’elle contient une liaison C=O très polarisée.","aide":"Le butane ne contient que des liaisons C–C et C–H, très peu polarisées.","type":"zone","document":"teb","multiple":false},{"enonce":"De combien de degrés la propanone bout-elle plus haut que le butane ?","aide":"Attention au signe de la température d’ébullition du butane : 56 − (−1).","type":"nombre","unite":"°C"},{"enonce":"Comment expliquer cet écart alors que les masses molaires sont identiques ?","aide":"Pense aux attractions entre molécules : à masse comparable, laquelle s’attire le plus ?","type":"choix","options":[{"id":"a","texte":"Les molécules polaires s’attirent davantage, il faut plus d’énergie pour les séparer"},{"id":"b","texte":"La propanone contient moins d’atomes de carbone, donc elle chauffe plus vite"},{"id":"c","texte":"La propanone est plus lourde que le butane, donc plus difficile à vaporiser"},{"id":"d","texte":"Le butane est plus polaire, ce qui l’empêche de bouillir facilement"}],"multiple":false},{"enonce":"Le diiode I₂ est un solide apolaire. Quelle justification est correcte ?","aide":"Qu’est-ce qui rend une liaison polarisée ?","type":"choix","options":[{"id":"a","texte":"Sa liaison I–I relie deux atomes identiques, elle n’est donc pas polarisée"},{"id":"b","texte":"La molécule I₂ est coudée, ce qui compense les charges"},{"id":"c","texte":"Un solide ne peut jamais être polaire"},{"id":"d","texte":"Les atomes d’iode ont la plus grande électronégativité du tableau périodique"}],"multiple":false}]}$ex$::jsonb,
