   $ex${"titre":"La glace qui fond dans le verre","competence":"analyser-document","situation":"Noé regarde un glaçon fondre dans un verre d’eau, puis l’eau s’évaporer d’une casserole sur le feu. Il se demande ce qui se passe à l’échelle des molécules H₂O.","documents":[{"id":"etats","type":"chaine","titre":"Les trois états de l’eau","disposition":"ligne","noeuds":[{"id":"z1","texte":"Glace","emoji":"🧊"},{"id":"z2","texte":"Eau liquide","emoji":"💧"},{"id":"z3","texte":"Vapeur","emoji":"☁️"}],"liens":[{"de":"z1","a":"z2","texte":"fusion"},{"de":"z2","a":"z3","texte":"ébullition"}]}],"questions":[{"enonce":"Touche l’état dans lequel les molécules d’eau interagissent le moins entre elles.","aide":"Dans quel état les molécules sont-elles les plus éloignées les unes des autres ?","type":"zone","document":"etats","multiple":false},{"enonce":"Quand la glace fond, que se passe-t-il à l’intérieur des molécules d’eau ?","aide":"La fusion est un changement d’état, pas une réaction chimique.","type":"choix","options":[{"id":"a","texte":"Les atomes d’hydrogène quittent les molécules d’eau pour former d’autres atomes"},{"id":"b","texte":"Les liaisons covalentes O–H restent intactes, seules les interactions entre molécules changent"},{"id":"c","texte":"Les liaisons covalentes O–H se rompent, car la molécule reçoit de l’énergie en fondant"},{"id":"d","texte":"Les molécules d’eau se transforment peu à peu en molécules de dihydrogène"}],"multiple":false},{"enonce":"Que rompt chacun de ces phénomènes ?","aide":"Un changement d’état ne change pas la nature des molécules ; une réaction chimique, si.","type":"categories","categories":[{"id":"c0","texte":"Interactions entre molécules"},{"id":"c1","texte":"Liaisons covalentes"}],"items":[{"id":"i0","texte":"Vaporisation de l’éthanol"},{"id":"i1","texte":"Ébullition de l’eau"},{"id":"i2","texte":"Fusion de la glace"},{"id":"i3","texte":"Combustion du méthane"},{"id":"i4","texte":"Électrolyse de l’eau"}]}]}$ex$::jsonb,
